  // === PÁGINA: BAR BRIZA ===
  badge_briza: { pt: "🎶 Samba & Vibes", en: "🎶 Samba & Vibes", es: "🎶 Samba y Vibras", zh: "🎶 桑巴与活力" },
  title_briza: { pt: "Briza da Gigóia", en: "Briza da Gigóia", es: "Briza da Gigóia", zh: "吉戈亚微风" },
  sub_briza: { pt: "Gastronomia, música ao vivo e eventos em um ambiente agradável à beira da lagoa.", en: "Gastronomy, live music, and events in a pleasant environment by the lagoon.", es: "Gastronomía, música en vivo y eventos en un ambiente agradable a orillas de la laguna.", zh: "美食、现场音乐和活动，在泻湖边令人愉悦的环境中。" },
  
  briza_sobre_titulo: { pt: "Sobre o Espaço", en: "About the Space", es: "Sobre el Espacio", zh: "关于空间" },
  briza_p1: { pt: "Localizado logo na entrada principal da ilha, o <strong>Briza da Gigóia</strong> é um espaço que combina gastronomia, música e eventos em um ambiente agradável à beira da lagoa. O bar oferece uma vista privilegiada e um clima descontraído, perfeito para quem quer aproveitar o melhor da atmosfera única da Ilha da Gigóia.", en: "Located right at the main entrance of the island, <strong>Briza da Gigóia</strong> is a space that combines gastronomy, music, and events in a pleasant environment by the lagoon. The bar offers a privileged view and a relaxed atmosphere, perfect for those who want to enjoy the best of Gigóia Island's unique vibe.", es: "Ubicado justo en la entrada principal de la isla, el <strong>Briza da Gigóia</strong> es un espacio que combina gastronomía, música y eventos en un ambiente agradable a orillas de la laguna. El bar ofrece una vista privilegiada y un clima relajado, perfecto para quienes desean disfrutar de lo mejor de la atmósfera única de la Isla Gigóia.", zh: "位于小岛主入口，<strong>吉戈亚微风</strong>将美食、音乐和活动融合在泻湖边怡人的环境中。酒吧提供优越视野和轻松氛围，非常适合享受吉戈亚岛独特魅力的人们。" },
  briza_p2: { pt: "O ambiente é conhecido por ser versátil e acolhedor, funcionando tanto para um almoço tranquilo quanto para encontros entre amigos ou celebrações especiais. O espaço também pode ser reservado para <strong>eventos e comemorações</strong>, sendo uma ótima opção para quem deseja celebrar aniversários, confraternizações ou encontros particulares em um cenário diferente, cercado pela natureza da lagoa.", en: "The environment is known for being versatile and welcoming, working both for a quiet lunch and for gatherings with friends or special celebrations. The space can also be reserved for <strong>events and celebrations</strong>, making it a great option for those wishing to celebrate birthdays, get-togethers, or private meetings in a different setting, surrounded by the lagoon's nature.", es: "El ambiente es conocido por ser versátil y acogedor, funcionando tanto para un almuerzo tranquilo como para encuentros entre amigos o celebraciones especiales. El espacio también puede ser reservado para <strong>eventos y conmemoraciones</strong>, siendo una excelente opción para quienes desean celebrar cumpleaños, reuniones o encuentros privados en un escenario diferente, rodeado de la naturaleza de la laguna.", zh: "这里氛围多变而温馨，既适合安静午餐，也适合朋友聚会或特别庆典。场地可预订举办<strong>活动和庆典</strong>，是在与众不同、被泻湖自然环绕的场所庆祝生日、聚会或私人会面的绝佳选择。" },
  briza_p3: { pt: "Outro destaque do Briza é a programação musical. Frequentemente acontecem apresentações de música ao vivo, especialmente <strong>rodas de samba aos finais de semana</strong>, que dão ainda mais vida ao lugar e transformam o ambiente em um ponto animado da noite da ilha.", en: "Another highlight of Briza is the musical programming. Live music performances frequently take place, especially <strong>samba circles on weekends</strong>, which bring even more life to the place and transform the environment into a lively spot for the island's nightlife.", es: "Otro destaque del Briza es la programación musical. Frecuentemente hay presentaciones de música en vivo, especialmente <strong>ruedas de samba los fines de semana</strong>, que dan aún más vida al lugar y transforman el ambiente en un punto animado de la noche isleña.", zh: "另一大亮点是音乐节目。经常有现场音乐表演，尤其是<strong>周末的桑巴圈</strong>，为这里带来更多活力，使之成为岛上夜生活的热点。" },
  briza_p4: { pt: "Com boa comida, música e uma paisagem encantadora, o Briza da Gigóia se tornou um espaço ideal para quem quer curtir bons momentos, comemorar datas especiais ou simplesmente aproveitar a energia boêmia das ilhas da Barra da Tijuca.", en: "With good food, music, and an enchanting landscape, Briza da Gigóia has become an ideal space for those who want to enjoy good times, celebrate special dates, or simply soak up the bohemian energy of the Barra da Tijuca islands.", es: "Con buena comida, música y un paisaje encantador, el Briza da Gigóia se ha convertido en un espacio ideal para quienes quieren disfrutar de buenos momentos, celebrar fechas especiales o simplemente aprovechar la energía bohemia de las islas de Barra da Tijuca.", zh: "有了美食、音乐和迷人的风景，吉戈亚微风已成为享受美好时光、庆祝特别日子或简单沉浸在巴拉达蒂茹卡群岛波西米亚气息的理想之地。" },
  
