  // === PÁGINA: BAR CAIÇARAS ===
  title_caicara: { pt: "Bar Caiçara", en: "Caiçara Bar", es: "Bar Caiçara", zh: "海滨酒吧" },
  sub_caicara: { pt: "Arte, música, gastronomia e um pôr do sol inesquecível na Ilha da Gigóia.", en: "Art, music, gastronomy, and an unforgettable sunset on Gigóia Island.", es: "Arte, música, gastronomía y un atardecer inolvidable en la Isla Gigóia.", zh: "艺术、音乐、美食和吉戈亚岛上令人难忘的日落。" },
  caicara_sobre_titulo: { pt: "Sobre o Bar", en: "About the Bar", es: "Sobre el Bar", zh: "关于酒吧" },
  
  caicara_p1: { pt: "Localizado na Ilha da Gigóia, o <strong>Bar Caiçara</strong> é um dos lugares mais autênticos e culturais da região. Muito mais do que um simples bar, o espaço mistura gastronomia, arte e música, criando um ambiente único para quem visita a ilha.", en: "Located on Gigóia Island, <strong>Bar Caiçara</strong> is one of the most authentic and cultural places in the region. Much more than just a bar, the space mixes gastronomy, art, and music, creating a unique environment for those visiting the island.", es: "Ubicado en la Isla Gigóia, el <strong>Bar Caiçara</strong> es uno de los lugares más auténticos y culturales de la región. Mucho más que un simple bar, el espacio mezcla gastronomía, arte y música, creando un ambiente único para quienes visitan la isla.", zh: "位于吉戈亚岛，<strong>海滨酒吧</strong>是该地区最真实、最具文化气息的地方之一。不仅仅是一个普通酒吧，这里融合了美食、艺术和音乐，为游客创造了独特的环境。" },
  caicara_p2: { pt: "Um dos grandes diferenciais da casa é seu <strong>palco cultural</strong>, onde acontecem apresentações de música ao vivo, teatro e eventos artísticos, transformando o local em um verdadeiro ponto de encontro para quem aprecia cultura e boa energia.", en: "One of the great differentials of the house is its <strong>cultural stage</strong>, which hosts live music performances, theater, and artistic events, transforming the place into a true meeting point for those who appreciate culture and good energy.", es: "Uno de los grandes diferenciales de la casa es su <strong>escenario cultural</strong>, donde se realizan presentaciones de música en vivo, teatro y eventos artísticos, transformando el lugar en un verdadero punto de encuentro para quienes aprecian la cultura y la buena energía.", zh: "其重要特色之一是<strong>文化舞台</strong>，这里举办现场音乐表演、戏剧和艺术活动，使其成为欣赏文化和充满活力的真正聚集地。" },
  caicara_p3: { pt: "O cardápio é bem variado e traz excelentes petiscos e pratos inspirados na culinária brasileira e caiçara, com destaque para frutos do mar, pastéis e diversas opções para compartilhar entre amigos. Tudo isso acompanhado de chopp sempre muito gelado e ótimas caipirinhas, perfeitas para o clima descontraído da ilha.", en: "The menu is quite varied and features excellent snacks and dishes inspired by Brazilian and caiçara cuisine, with highlights including seafood, pastéis, and various options to share with friends. All this accompanied by ice-cold draft beer and great caipirinhas, perfect for the island's relaxed atmosphere.", es: "El menú es muy variado y ofrece excelentes tapas y platos inspirados en la cocina brasileña y caiçara, destacando los mariscos, empanadas y diversas opciones para compartir entre amigos. Todo esto acompañado de cerveza de barril siempre muy fría y excelentes caipirinhas, perfectas para el ambiente relajado de la isla.", zh: "菜单种类丰富，提供以巴西海岸料理为灵感的优质小吃和菜肴，海鲜、炸饺子和各种适合朋友分享的选项尤为突出。一切都配以永远冰爽的生啤和美妙的卡比里尼亚鸡尾酒，非常适合岛上轻松的氛围。" },
  caicara_p4: { pt: "Outro espetáculo à parte é o <strong>pôr do sol</strong>. Com vista privilegiada para a lagoa e para a natureza ao redor, o Bar Caiçara se transforma no fim da tarde em um dos melhores lugares da Ilha da Gigóia para relaxar, apreciar a paisagem e curtir a vibe tranquila das ilhas.", en: "Another spectacle is the <strong>sunset</strong>. With a privileged view of the lagoon and surrounding nature, Bar Caiçara transforms in the late afternoon into one of the best places on Gigóia Island to relax, enjoy the scenery, and soak up the peaceful vibe of the islands.", es: "Otro espectáculo aparte es el <strong>atardecer</strong>. Con una vista privilegiada a la laguna y la naturaleza circundante, el Bar Caiçara se transforma al final de la tarde en uno de los mejores lugares de la Isla Gigóia para relajarse, apreciar el paisaje y disfrutar de la vibra tranquila de las islas.", zh: "另一大亮点是<strong>日落</strong>。俯瞰泻湖和周边自然风光，海滨酒吧在傍晚时分成为吉戈亚岛上最好的放松、欣赏风景和感受群岛宁静氛围的地方之一。" },
  caicara_p5: { pt: "Entre boa música, arte, petiscos e uma paisagem incrível, o Bar Caiçara é uma parada obrigatória para quem quer viver a essência cultural e boêmia da Ilha da Gigóia.", en: "Between good music, art, snacks, and an incredible landscape, Bar Caiçara is a mandatory stop for anyone who wants to experience the cultural and bohemian essence of Gigóia Island.", es: "Entre buena música, arte, tapas y un paisaje increíble, el Bar Caiçara es una parada obligatoria para quienes desean vivir la esencia cultural y bohemia de la Isla Gigóia.", zh: "在美妙的音乐、艺术、小吃和令人叹为观止的风景之间，海滨酒吧是任何想要体验吉戈亚岛文化与波西米亚精髓的人必到的地方。" },
  
  caicara_esp_titulo: { pt: "A Essência", en: "The Essence", es: "La Esencia", zh: "精髓" },
  caicara_esp_1: { pt: "✓ Música ao vivo e Arte", en: "✓ Live Music and Art", es: "✓ Música en vivo y Arte", zh: "✓ 现场音乐与艺术" },
  caicara_esp_2: { pt: "✓ Petiscos e Frutos do Mar", en: "✓ Snacks and Seafood", es: "✓ Tapas y Mariscos", zh: "✓ 小吃与海鲜" },
  caicara_esp_3: { pt: "✓ Chopp gelado e Caipirinhas", en: "✓ Ice-cold Draft Beer and Caipirinhas", es: "✓ Cerveza de barril fría y Caipirinhas", zh: "✓ 冰镇生啤与卡比里尼亚" },
  caicara_esp_4: { pt: "✓ Palco Cultural", en: "✓ Cultural Stage", es: "✓ Escenario Cultural", zh: "✓ 文化舞台" },
  
  caicara_amb_titulo: { pt: "Ambiente", en: "Atmosphere", es: "Ambiente", zh: "氛围" },
  caicara_amb_p: { pt: "Descontraído, boêmio e com vista privilegiada.", en: "Relaxed, bohemian, and with a privileged view.", es: "Relajado, bohemio y con una vista privilegiada.", zh: "轻松、波西米亚风，视野优越。" },
  
