  badge_venti: { pt: "🏡 Conforto Familiar", en: "🏡 Family Comfort", es: "🏡 Confort Familiar", zh: "🏡 家庭舒适" },
  title_venti: { pt: "Casa Venti", en: "Casa Venti", es: "Casa Venti", zh: "文蒂之家" },
  sub_venti: { pt: "Um duplex completo em condomínio tranquilo, ideal para famílias e grupos que buscam o clima típico da ilha.", en: "A complete duplex in a quiet condominium, ideal for families and groups seeking the typical island vibe.", es: "Un dúplex completo en un condominio tranquilo, ideal para familias y grupos que buscan el clima típico de la isla.", zh: "安静社区内的完整复式公寓，非常适合寻求岛上典型氛围的家庭和团体。" },
  
  venti_sobre_titulo: { pt: "Sobre a Casa", en: "About the House", es: "Sobre la Casa", zh: "关于房屋" },
  venti_p1: { pt: "A <strong>Casa Venti</strong> é uma hospedagem muito bem avaliada no Airbnb localizada na Ilha da Gigóia. O espaço é um duplex completo dentro de um condomínio super tranquilo na ilha, sendo uma ótima opção para famílias ou pequenos grupos que querem passar alguns dias explorando a região.", en: "<strong>Casa Venti</strong> is a highly rated Airbnb accommodation located on Gigóia Island. The space is a complete duplex inside a super quiet condominium on the island, making it a great option for families or small groups who want to spend a few days exploring the region.", es: "La <strong>Casa Venti</strong> es un alojamiento muy bien valorado en Airbnb situado en la Isla Gigóia. El espacio es un dúplex completo dentro de un condominio súper tranquilo en la isla, siendo una gran opción para familias o pequeños grupos que quieren pasar unos días explorando la región.", zh: "<strong>文蒂之家</strong>是在Airbnb上评价很高的住宿，位于吉戈亚岛上一个超级安静的社区内的完整复式公寓，是想要花几天时间探索该地区的家庭或小型团体的好选择。" },
  venti_p2: { pt: "A casa tem um ambiente confortável e totalmente equipado, com áreas internas amplas e um pequeno jardim com churrasqueira e rede, criando um clima bem típico da ilha.", en: "The house has a comfortable and fully equipped environment, with spacious indoor areas and a small garden with a barbecue and a hammock, creating a very typical island atmosphere.", es: "La casa tiene un ambiente confortable y totalmente equipado, con amplias áreas internas y un pequeño jardín con barbacoa y hamaca, creando un clima muy típico de la isla.", zh: "房屋环境舒适完备，内部宽敞，有带烧烤架和吊床的小花园，营造出非常典型的岛屿气息。" },
  
