  // === PÁGINA: EXPERIÊNCIA COMPLETA ===
  badge_melhor_ilha: { pt: "✨ O Melhor da Ilha", en: "✨ The Best of the Island", es: "✨ Lo Mejor de la Isla", zh: "✨ 小岛精华" },
  title_exp_completa: { pt: "Experiência Completa", en: "Complete Experience", es: "Experiencia Completa", zh: "完整体验" },
  sub_exp_completa: { pt: "Não escolha apenas um lugar, viva a Ilha inteira. Criamos o roteiro ideal para você aproveitar cada segundo deste refúgio.", en: "Don't just choose one place, live the entire Island. We created the ideal itinerary for you to enjoy every second of this refuge.", es: "No elijas solo un lugar, vive la Isla entera. Creamos el itinerario ideal para que disfrutes cada segundo de este refugio.", zh: "不要只选择一个地方，体验整个小岛。我们为您创造了理想的行程，让您享受这个避难所的每一秒。" },
  
  exp_c1_t: { pt: "1. A Chegada", en: "1. The Arrival", es: "1. La Llegada", zh: "1. 抵达" },
  exp_c1_d: { pt: "Comece com uma travessia panorâmica pelos canais da \"Veneza Carioca\", observando a fauna local e o clima único da Ilha.", en: "Start with a panoramic crossing through the canals of the \"Carioca Venice\", observing the local fauna and the unique climate of the Island.", es: "Comienza con una travesía panorámica por los canales de la \"Venecia Carioca\", observando la fauna local y el clima único de la Isla.", zh: "从穿越\"里约威尼斯\"运河的全景之旅开始，观察当地动物和岛屿独特的氛围。" },
  
  exp_c2_t: { pt: "2. Gastronomia", en: "2. Gastronomy", es: "2. Gastronomía", zh: "2. 美食" },
  exp_c2_d: { pt: "Um almoço inesquecível em um dos nossos restaurantes selecionados, com o melhor dos frutos do mar e tempero caiçara.", en: "An unforgettable lunch in one of our selected restaurants, with the best seafood and caiçara seasoning.", es: "Un almuerzo inolvidable en uno de nuestros restaurantes seleccionados, con lo mejor de los mariscos y el sazón caiçara.", zh: "在我们精选的餐厅之一享用难忘的午餐，品尝最好的海鲜和海岸风味。" },
  
  exp_c3_t: { pt: "3. Pôr do Sol", en: "3. Sunset", es: "3. Puesta de Sol", zh: "3. 日落" },
  exp_c3_d: { pt: "Feche o dia com um drink artesanal em um deck exclusivo, assistindo ao sol se pôr atrás da Pedra da Gávea.", en: "End the day with an artisanal drink on an exclusive deck, watching the sun set behind Pedra da Gávea.", es: "Termina el día con una bebida artesanal en una terraza exclusiva, viendo la puesta de sol detrás de la Pedra da Gávea.", zh: "在专属露台上享用手工饮品，欣赏太阳在加维亚石后落下的美景。" },
  
  exp_banner_t: { pt: "Quer esse roteiro planejado para você?", en: "Do you want this itinerary planned for you?", es: "¿Quieres este itinerario planificado para ti?", zh: "想要为您规划这个行程吗？" },
  exp_banner_d: { pt: "A Gigi organiza sua reserva, indica os melhores horários e garante que sua experiência seja impecável.", en: "Gigi organizes your reservation, indicates the best times, and ensures your experience is impeccable.", es: "Gigi organiza tu reserva, indica los mejores horarios y asegura que tu experiencia sea impecable.", zh: "吉吉安排您的预订，推荐最佳时间，确保您的体验无懈可击。" },
  btn_reservar_exp_gigi: { pt: "Reservar Experiência com a Gigi", en: "Book Experience with Gigi", es: "Reservar Experiencia con Gigi", zh: "通过吉吉预订体验" },

  // === PÁGINA: FALE CONOSCO (VERSÃO GIGI DATILÓGRAFA) ===
  pg_fale_h1: { pt: "Fale Conosco", en: "Contact Us", es: "Contáctenos" },
  pg_fale_p: { pt: "Dúvidas, anúncios ou parcerias? Envie uma mensagem para nós.", en: "Questions, ads, or partnerships? Send us a message.", es: "¿Dudas, anuncios o asociaciones? Envíenos un mensaje." },
  fc_intro: { pt: "Estamos aqui para ajudar! Se você tem alguma dúvida sobre a ilha, deseja anunciar seu negócio no Portal Ilha da Gigóia ou propor uma parceria comercial, basta preencher o formulário abaixo que retornaremos em breve.", en: "We're here to help! If you have any questions about the island, want to advertise your business on the Gigóia Island Portal, or propose a business partnership, just fill out the form below and we'll get back to you soon.", es: "¡Estamos aquí para ayudar! Si tiene alguna pregunta sobre la isla, desea anunciar su negocio en el Portal Isla Gigóia o proponer una asociación comercial, simplemente complete el formulario a continuación y le responderemos pronto." },
