  sub_pass_rotas: { pt: "Roteiros de barco, paradas para fotos, horários ideais e dicas do que levar para aproveitar melhor.", en: "Boat itineraries, photo stops, ideal times, and tips on what to bring to enjoy it better.", es: "Itinerarios en barco, paradas para fotos, horarios ideales y consejos sobre qué llevar para disfrutar mejor." },
  
  // Detalhamento dos Cards (usados pelo SITE.pages["passeios-rotas"] no app.js)
  page_pass_c1_d: { pt: "Passeio de barco até o arquipélago. Águas cristalinas e fotos incríveis.", en: "Boat tour to the archipelago. Crystal clear waters and amazing photos.", es: "Paseo en barco al archipiélago. Aguas cristalinas y fotos increíbles.", zh: "在里约最美的水域中浮潜，与海龟共游" },
  page_pass_c2_d: { pt: "Explore a rica biodiversidade da lagoa e o safári urbano.", en: "Explore the rich biodiversity of the lagoon and the urban safari.", es: "Explora la rica biodiversidad de la laguna y el safari urbano.", zh: "在运河中观看凯门鳄、水豚和鸟类" },
  page_pass_c3_d: { pt: "Navegue pelos canais até chegar à bela e preservada Praia da Reserva.", en: "Sail through the canals until you reach the beautiful and preserved Reserva Beach.", es: "Navega por los canales hasta llegar a la hermosa y preservada Playa Reserva.", zh: "穿越马拉佩恩迪运河前往自然海滩" },
  page_pass_c4_d: { pt: "Aventura e adrenalina explorando as lagoas no seu próprio ritmo.", en: "Adventure and adrenaline exploring the lagoons at your own pace.", es: "Aventura y adrenalina explorando las lagunas a tu propio ritmo.", zh: "在泻湖水面上的肾上腺素和自由" },
