  title_veneza: { pt: "Veneza Carioca", en: "Veneza Carioca", es: "Veneza Carioca", zh: "里约威尼斯" },
  sub_veneza: { pt: "Ambiente intimista, acolhedor e com decoração exclusiva. O refúgio perfeito na tranquila Ilha Primeira.", en: "Intimate, welcoming atmosphere with exclusive decor. The perfect refuge on peaceful Ilha Primeira.", es: "Ambiente íntimo, acogedor y con decoración exclusiva. El refugio perfecto en la tranquila Ilha Primeira.", zh: "亲密、温馨的氛围，独特的装饰。宁静的伊岛一号上的完美避难所。" },
  veneza_p1: { pt: "O <strong>Veneza Carioca Hotel Boutique</strong> é um espaço pensado nos mínimos detalhes para oferecer uma experiência inesquecível. Localizado na Ilha Primeira, ele combina o charme de uma pousada exclusiva com o conforto de um hotel boutique.", en: "<strong>Veneza Carioca Hotel Boutique</strong> is a space designed in every detail to offer an unforgettable experience. Located on Ilha Primeira, it combines the charm of an exclusive inn with the comfort of a boutique hotel.", es: "El <strong>Veneza Carioca Hotel Boutique</strong> es un espacio pensado en los mínimos detalles para ofrecer una experiencia inolvidable. Ubicado en la Ilha Primeira, combina el encanto de una posada exclusiva con el confort de un hotel boutique.", zh: "<strong>里约威尼斯精品酒店</strong>是一个在每一个细节上都精心设计的空间，提供难忘的体验。位于伊岛一号，它将精品旅馆的魅力与精品酒店的舒适融为一体。" },
  veneza_p2: { pt: "Ideal para casais em viagens românticas ou viajantes que buscam sossego longe do barulho da cidade, mas com a facilidade de estar a poucos minutos do metrô Jardim Oceânico e da praia da Barra.", en: "Ideal for couples on romantic trips or travelers seeking peace away from city noise, yet with the ease of being just minutes from Jardim Oceânico metro and Barra beach.", es: "Ideal para parejas en viajes románticos o viajeros que buscan tranquilidad lejos del ruido de la ciudad, pero con la facilidad de estar a pocos minutos del metro Jardim Oceânico y de la playa de Barra.", zh: "非常适合浪漫旅行中的情侣或寻求远离城市喧嚣的宁静、同时又靠近花园海洋地铁站和巴拉海滩的旅行者。" },
  veneza_dest_1: { pt: "✓ Decoração exclusiva", en: "✓ Exclusive decor", es: "✓ Decoración exclusiva", zh: "✓ 独特装饰" },
