  ee_onde_celebrar_t: { pt: "Onde celebrar", en: "Where to celebrate", es: "Dónde celebrar", zh: "在哪里庆祝" },
  ee_onde_celebrar_d: { pt: "Conheça as melhores opções de ambientes para o seu evento.", en: "Discover the best options of environments for your event.", es: "Conoce las mejores opciones de ambientes para tu evento.", zh: "了解适合您活动的最佳环境选项。" },
  card_gaivota_ee_d: { pt: "Localizado na Ilha Primeira, combina vista privilegiada com atmosfera elegante. Perfeito para casamentos intimistas, festas e eventos corporativos.", en: "Located on Ilha Primeira, it combines a privileged view with an elegant atmosphere. Perfect for intimate weddings, parties, and corporate events.", es: "Ubicado en Ilha Primeira, combina una vista privilegiada con una atmósfera elegante. Perfecto para bodas íntimas, fiestas y eventos corporativos.", zh: "位于伊岛一号，结合优越视野与优雅氛围。非常适合私密婚礼、派对和企业活动。" },
  card_solar_ee_d: { pt: "Arquitetura colonial e amplos jardins. Oferece produção personalizada de alta gastronomia para casamentos, festas de 15 anos e celebrações grandiosas.", en: "Colonial architecture and vast gardens. Offers personalized high-gastronomy production for weddings, 15th birthday parties, and grand celebrations.", es: "Arquitectura colonial y amplios jardines. Ofrece producción personalizada de alta gastronomía para bodas, fiestas de 15 años y grandes celebraciones.", zh: "殖民建筑和宽阔花园。提供婚礼、15岁成人礼和盛大庆典的个性化高级美食制作。" },
  card_oasis_ee_d: { pt: "Mistura restaurante, lounge e espaço para festas privadas. Cenário charmoso para almoços relaxantes que ganha um clima animado e musical à noite.", en: "Mixes restaurant, lounge, and space for private parties. Charming setting for relaxing lunches that gains a lively and musical atmosphere at night.", es: "Mezcla restaurante, lounge y espacio para fiestas privadas. Entorno encantador para almuerzos relajantes que adquiere un ambiente animado y musical por la noche.", zh: "融合餐厅、休闲吧和私人派对场地。迷人的场所，放松的午餐在夜晚变得充满活力和音乐。" },
  card_mara_ee_d: { pt: "Reúne gastronomia, drinks tropicais e um pôr do sol inesquecível. O cenário perfeito para confraternizações e encontros descontraídos entre amigos.", en: "Gathers gastronomy, tropical drinks, and an unforgettable sunset. The perfect setting for gatherings and relaxed meetings among friends.", es: "Reúne gastronomía, tragos tropicales y un atardecer inolvidable. El escenario perfecto para confraternizaciones y encuentros relajados entre amigos.", zh: "融合美食、热带饮品和令人难忘的日落。朋友间聚会和轻松会面的完美场景。" },

